import { readFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

import type { Catalog } from "./catalog-layer.js";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
// Generated by scripts/build-light-catalog.mjs from Blizzard's LightData.xml, parents resolved.
const CATALOG_PATH = path.resolve(__dirname, "../../data/light-catalog.json");

/** Brightness (luminance; the key's times its multiplier), hue in degrees and saturation 0-1. */
export type LightTone = { readonly brightness: number; readonly hue: number; readonly saturation: number };

export type StockLight = {
  /** The package that first defines it (liberty, swarm, void, voidstory, novastoryassets...). */
  readonly package: string;
  /** Its Editor group: Tilesets, StoryModeCutScenes, CinematicsTerran... */
  readonly group?: string;
  /** More than one when the light cycles through times of day; the catalog keeps the first. */
  readonly timesOfDay?: number;
  readonly summary: { readonly ambient: LightTone; readonly key: LightTone; readonly exposure: number };
  /**
   * Its fields, flattened by path: "ToDInfoArray/0/AmbientColor", "ToDInfoArray/0/Param/HDRExposure",
   * "ToDInfoArray/0/DirectionalLight/Key/Color", "EditorCategories"...
   */
  readonly fields: Readonly<Record<string, string>>;
};

let catalog: Record<string, StockLight> | null = null;
const load = (): Record<string, StockLight> => (catalog ??= (JSON.parse(readFileSync(CATALOG_PATH, "utf8")) as { lights: Record<string, StockLight> }).lights);

/** A stock light (portrait and UI lights left out), or undefined. */
export function getStockLight(id: string): StockLight | undefined {
  return load()[id];
}

/** Whether a Light is the game's (data/light-catalog.json) or the Campaign Mod's: one a map can name, though only a stock one can be copied. */
export function isKnownLight(catalog: Catalog, id: string): boolean {
  return getStockLight(id) !== undefined || catalog.lights.has(id);
}
